using System;
using UnityEngine;
public static class ValidateTyrePressure {
public static string Main(){if(!Application.isPlaying)throw new Exception("Requires Play");var source=UnityEngine.Object.FindAnyObjectByType<VehiclePhysics>();var clone=UnityEngine.Object.Instantiate(source.gameObject,source.transform.position+Vector3.up*200,Quaternion.identity);try{var v=clone.GetComponent<VehiclePhysics>();v.automaticSimulation=false;v.externalControl=true;clone.GetComponent<VehiclePlayerInput>().enabled=false;clone.GetComponent<VehicleAudio>().enabled=false;var rb=clone.GetComponent<Rigidbody>();rb.linearVelocity=Vector3.zero;rb.angularVelocity=Vector3.zero;var pressure=clone.GetComponent<VehicleTyrePressure>();if(pressure==null)throw new Exception("Pressure component missing");v.SetInput(default);if(pressure.RequestPressure(1.2f))throw new Exception("Pressure changed without parking brake");v.SetInput(new VehicleControlInput{handbrake=true});if(!pressure.RequestPressure(1.2f))throw new Exception(pressure.Message);pressure.Advance(5);float partial=pressure.PressureBar;if(partial>=2.2f||partial<=1.2f)throw new Exception("Instant/no deflation "+partial);v.SetInput(default);pressure.Advance(.1f);if(pressure.Adjusting||pressure.PressureBar!=partial)throw new Exception("Moving cancellation loses actual pressure");v.SetInput(new VehicleControlInput{handbrake=true});if(!pressure.RequestPressure(1.2f))throw new Exception("Cannot resume");pressure.Advance(100);float soilFactor=pressure.SoilLoadMultiplier,grip=pressure.SoftGripMultiplier;if(Mathf.Abs(pressure.PressureBar-1.2f)>.001f||soilFactor>=1||grip<=1||grip>1.29f)throw new Exception("No bounded soft-soil effect");if(!pressure.RequestPressure(2.2f))throw new Exception("Cannot inflate");pressure.Advance(10);float pumping=pressure.PressureBar;if(pumping<=1.2f||pumping>=2.2f)throw new Exception("Instant/no inflation");pressure.Advance(100);if(Mathf.Abs(pressure.PressureBar-2.2f)>.001f)throw new Exception("Inflation did not finish");if(pressure.RequestPressure(float.NaN)||pressure.RequestPressure(-1)||pressure.RequestPressure(8))throw new Exception("Invalid pressure accepted");pressure.ToggleWindow();if(!pressure.WindowOpen)throw new Exception("No window");pressure.ToggleWindow();return "PASS tyre pressure 2.2 -> "+partial.ToString("F2")+" -> 1.2 -> "+pumping.ToString("F2")+" -> 2.2 bar; parking/cancellation/range checks; soft soil load="+soilFactor.ToString("F2")+", grip="+grip.ToString("F2")+"; window toggle.";}finally{UnityEngine.Object.DestroyImmediate(clone);}}
}
